    `<input type="hidden" name="token" value="${esc(t)}">` +
    btn('price', 'Cena') + btn('time', 'Termin realizacji') + btn('other_offer', 'Wybrali Państwo inną ofertę') + btn('other', 'Inny powód') +
    `</form>`),
